/* Progressive enhancement: no tracking, no network requests, no storage. */
(() => {
  if (window.__cinsInit) return; window.__cinsInit = true;
  const CITATION_DATA = {"1": {"id": 1, "title": "AI-generated CSAM trends, 2025 Data & Insights Report", "publisher": "Internet Watch Foundation", "date": "2025 reporting year (published early 2026)", "locator": "Emerging and Persistent Harms Section; Table 1 & Key Figures", "status": "Primary source checked", "population": "Operational reports received and assessed by IWF technical analysts worldwide", "geo": "Global (UK-headquartered reporting hub)", "claim": "491 operational reports in 2025 vs 193 in 2024; 8,029 assessed realistic criminal AI media files in 2025.", "limits": "Reflects reports received and assessed by hotline analysts; operational reports do not equate to unique children or victims.", "url": "https://www.iwf.org.uk/annual-data-insights-report-2025/emerging-and-persistent-harms/ai-generated-child-sexual-abuse-material/"}, "2": {"id": 2, "title": "AI-generated image trends, 2025 Data & Insights Report", "publisher": "Internet Watch Foundation", "date": "2025 reporting year", "locator": "Image Insights Section; Still Images Subsection p. 12", "status": "Primary source checked", "population": "449,298 confirmed criminal still images assessed by IWF analysts", "geo": "Global", "claim": "4,586 criminal AI-generated still images among 449,298 total criminal images assessed in 2025; 81 additional prohibited still images.", "limits": "Assessment practices and crawling triggers affect numerator/denominator; images may depict multiple or repeated synthetic personas.", "url": "https://www.iwf.org.uk/annual-data-insights-report-2025/image-insights/ai-generated-images/"}, "3": {"id": 3, "title": "AI-generated video trends, 2025 Data & Insights Report", "publisher": "Internet Watch Foundation", "date": "2025 reporting year", "locator": "Video Insights Section; AI Video Subsection", "status": "Primary source checked", "population": "63,682 criminal videos assessed by IWF analysts in 2025", "geo": "Global", "claim": "3,443 photorealistic criminal AI videos confirmed in 2025 compared to 13 in 2024 (a >260-fold increase in assessed files).", "limits": "Detailed video series represents assessed media files; does not equate to discrete victim identities.", "url": "https://www.iwf.org.uk/annual-data-insights-report-2025/video-insights/ai-generated-videos/"}, "4": {"id": 4, "title": "More AI-generated abuse images found in first six months of 2026 than all of 2025", "publisher": "Internet Watch Foundation", "date": "July 2026", "locator": "News Release Headline & Paragraphs 2-4", "status": "Primary source checked", "population": "Hotline reports actioned during H1 2026", "geo": "Global (UK operational base)", "claim": "First-half 2026 photorealistic AI-generated still-image findings exceeded full-year 2025 total.", "limits": "Interim half-year observational finding; qualitative comparison based on ongoing analyst triage.", "url": "https://www.iwf.org.uk/news-media/news/more-ai-generated-child-sexual-abuse-images-found-in-the-first-six-months-of-2026-than-all-of-2025-iwf-warns"}, "5": {"id": 5, "title": "Executive Summary, Annual Data & Insights Report 2025", "publisher": "Internet Watch Foundation", "date": "2026 publication", "locator": "Executive Summary Key Metrics Table, p. 4", "status": "Primary source checked", "population": "451,210 total reports assessed; 311,610 confirmed as or linked to CSAM", "geo": "Global", "claim": "Online summary reconciles video metric at 3,443 AI-generated videos in 2025; explicitly warns against interpreting operational hotline numbers as global prevalence.", "limits": "Prior discrepancy between summary PDF and web table reconciled; figures represent hotline operational volume.", "url": "https://www.iwf.org.uk/annual-data-insights-report-2025/executive-summary/"}, "6": {"id": 6, "title": "Generative AI and Child Sexual Exploitation", "publisher": "National Center for Missing & Exploited Children", "date": "December 2025 update", "locator": "Analysis Subsection: Triage & Identification Rates", "status": "Primary source checked", "population": "Electronic Service Provider (ESP) CyberTipline reports flagged or categorized as AI-generated", "geo": "United States / Global ESP reports", "claim": "More than 158,000 images/videos categorized by NCMEC staff as AI-generated (2023-2025); providers proactively marked just over 11,000 during that same period.", "limits": "Highlights substantial gap between provider self-tagging and specialized analyst identification.", "url": "https://www.missingkids.org/theissues/generative-ai"}, "7": {"id": 7, "title": "CyberTipline 2025 Annual Data Release", "publisher": "National Center for Missing & Exploited Children", "date": "2026 release", "locator": "2025 Annual Report; Generative AI Nexus Category", "status": "Primary source checked", "population": "Over 36 million total CyberTipline incident reports processed in 2025", "geo": "United States and international ESP referrals", "claim": "2025 reports with a generative-AI nexus exceeded 400,000; over 182,000 involved possession, generation, or attempted generation of synthetic CSAM.", "limits": "Reports reflect automated platform hashes, user flags, and tip referrals; duplicates and automated bot submissions may be included.", "url": "https://www.ncmec.org/gethelpnow/cybertipline/cybertiplinedata"}, "8": {"id": 8, "title": "Releasing Re-LAION-5B: Remediation and Safety Statement", "publisher": "LAION (Large-scale Artificial Intelligence Open Network)", "date": "December 2023 / 2024 update", "locator": "Official Blog Announcement & Safety Statement", "status": "Primary source checked", "population": "5.85 billion web image-text pairs indexed in LAION-5B", "geo": "International Web Crawl (Common Crawl)", "claim": "Stanford Internet Observatory identified links to suspected CSAM in LAION-5B; LAION withdrew the dataset and collaborated with child safety groups to remediate the index.", "limits": "Self-reported remediation statement following independent academic audit by Stanford Internet Observatory.", "url": "https://laion.ai/blog/relaion-5b/"}, "9": {"id": 9, "title": "Hugging Face Content Policy & Code of Conduct", "publisher": "Hugging Face", "date": "Updated 2025 / accessed 2026", "locator": "Prohibited Content: Exploitative & Non-Consensual Imagery Clauses", "status": "Primary source checked", "population": "All public and private models, datasets, and Spaces hosted on huggingface.co", "geo": "Global platform", "claim": "Requires publishers to minimize risk of ML artifacts facilitating CSAM or non-consensual sexual depiction; provides reporting and takedown mechanisms.", "limits": "Terms document developer obligations; does not measure platform enforcement latency or automated blocking effectiveness.", "url": "https://huggingface.co/content-policy"}, "10": {"id": 10, "title": "Hub Documentation: Model Cards & Metadata Specifications", "publisher": "Hugging Face", "date": "2025-2026 documentation", "locator": "Model Card Specifications & YAML Frontmatter Standard", "status": "Primary source checked", "population": "Public repository guidelines for ML models", "geo": "Global", "claim": "Defines standardized metadata schema: intended uses, out-of-scope uses, bias/risk disclosures, and training data provenance.", "limits": "Model card population is voluntary; community models frequently omit out-of-scope warnings or safety tags.", "url": "https://huggingface.co/docs/hub/model-cards"}, "11": {"id": 11, "title": "High-Resolution Image Synthesis with Latent Diffusion Models", "publisher": "Rombach, Blattmann, Lorenz, Esser, & Ommer", "date": "CVPR 2022 (arXiv:2112.10752)", "locator": "Section 3: Method (Latent Diffusion Models); Section 4.3", "status": "Primary source checked", "population": "Autoencoding latent space trained on OpenImages and LAION subsets", "geo": "Academic research (LMU Munich, Runway)", "claim": "Operating diffusion processes in learned low-dimensional latent space reduces computational complexity while maintaining high perceptual fidelity.", "limits": "Foundational technical computer vision paper; does not address societal misuse vectors or non-consensual fine-tuning.", "url": "https://arxiv.org/abs/2112.10752"}, "12": {"id": 12, "title": "SDXL: Improving Latent Diffusion Models for High-Resolution Image Synthesis", "publisher": "Podell et al. (Stability AI)", "date": "July 2023 (arXiv:2307.01952)", "locator": "Section 2: Architecture (3x larger UNet, dual text encoders)", "status": "Primary source checked", "population": "Base model (3.5B parameters) and refinement pipeline", "geo": "Global open-weight release", "claim": "Introduces 3.5B-parameter architecture capable of native 1024x1024 image synthesis, serving as a primary base for thousands of subsequent community fine-tunes.", "limits": "Technical architectural specification; open weights enable unrestricted downstream local fine-tuning.", "url": "https://arxiv.org/abs/2307.01952"}, "13": {"id": 13, "title": "FLUX.1 schnell Model Card and Technical Release", "publisher": "Black Forest Labs", "date": "August 2024", "locator": "Model Details & License Specification (Apache 2.0)", "status": "Primary source checked", "population": "12-billion-parameter rectified flow transformer model", "geo": "Global", "claim": "FLUX.1-schnell released under Apache-2.0 license with 12B parameters; rectified flow transformer architecture allows high photorealism with few inference steps.", "limits": "Apache-2.0 open-source license allows unrestricted local modification and LoRA attachment.", "url": "https://huggingface.co/black-forest-labs/FLUX.1-schnell/blob/main/README.md"}, "14": {"id": 14, "title": "Qwen-Image Foundation Model Specification", "publisher": "Alibaba / Qwen Team", "date": "2025 release", "locator": "Model Card & Configuration File", "status": "Primary source checked", "population": "20B-parameter multimodal vision-language generation architecture", "geo": "Global open weights", "claim": "20-billion-parameter multimodal diffusion model capable of intricate prompt adherence and high-resolution rendering.", "limits": "Large model footprint; downstream community adapters bypass publisher safety alignment.", "url": "https://huggingface.co/Qwen/Qwen-Image"}, "15": {"id": 15, "title": "MOSS-Image Open Repository and Architecture Specification", "publisher": "OpenMOSS Research Team (Fudan University)", "date": "2025 release", "locator": "Repository README: Diffusion Transformer (DiT) Backbone Specifications", "status": "Primary source checked", "population": "5-billion-parameter open-weight visual foundation architecture", "geo": "Global open source", "claim": "5B-parameter DiT backbone demonstrating that high-capacity visual generation can be trained and run on accessible hardware.", "limits": "Research-grade release lacking embedded hardware watermarking or cryptographic provenance.", "url": "https://github.com/OpenMOSS/MOSS-Image"}, "16": {"id": 16, "title": "LoRA: Low-Rank Adaptation of Large Language Models", "publisher": "Hu, Shen, Wallis, Allen-Zhu, Li, Wang, Wang, & Chen", "date": "ICLR 2022 (arXiv:2106.09685)", "locator": "Section 3: Mathematical Formulation of Low-Rank Decomposition", "status": "Primary source checked", "population": "Empirical validation on transformer architectures (GPT, RoBERTa, diffusion models)", "geo": "Academic research (Microsoft)", "claim": "Freezes pretrained model weights and injects trainable rank decomposition matrices, reducing trainable parameters by up to 10,000x and GPU memory overhead by 3x.", "limits": "Originally designed for language models; widely adapted by open-source vision communities to specialize models on target individuals with <20 images.", "url": "https://arxiv.org/abs/2106.09685"}, "17": {"id": 17, "title": "Diffusers Library: Using and Training LoRAs for Diffusion Models", "publisher": "Hugging Face", "date": "2024-2026 documentation", "locator": "Diffusers Documentation: Parameter-Efficient Fine-Tuning Integration", "status": "Primary source checked", "population": "Diffusers Python library users and ecosystem models", "geo": "Global developer community", "claim": "Documents cross-compatibility of lightweight LoRA weights (tens to hundreds of MBs) across Stable Diffusion, SDXL, and Flux pipelines.", "limits": "Technical developer documentation; demonstrates that safety fine-tuning in base models can be inverted via modular adapters.", "url": "https://huggingface.co/docs/diffusers/en/training/lora"}, "18": {"id": 18, "title": "DreamBooth: Fine Tuning Text-to-Image Diffusion Models for Subject-Driven Generation", "publisher": "Ruiz, Li, Jampani, Pritch, Rubinstein, & Aberman", "date": "CVPR 2023 (arXiv:2208.12242)", "locator": "Section 3: Subject-Driven Generation Pipeline and Prior-Preservation Loss", "status": "Primary source checked", "population": "Subject personalization using 3-5 reference images", "geo": "Academic research (Google Research, Tel Aviv University)", "claim": "Enables subject-driven image generation from 3-5 photographs of a specific subject by binding a unique identifier to the target identity.", "limits": "Core technique hijacked by predatory undressing and deepfake tools to personalize sexual imagery onto non-consenting individuals.", "url": "https://arxiv.org/abs/2208.12242"}, "19": {"id": 19, "title": "Diffusers Documentation: Memory and Performance Optimization", "publisher": "Hugging Face", "date": "2025 documentation", "locator": "Techniques for VRAM Reduction: FP16, SDPA, CPU Offloading", "status": "Primary source checked", "population": "Consumer GPU hardware running generative pipelines", "geo": "Global", "claim": "Techniques such as 8-bit quantization, scaled dot-product attention, and offloading enable 12B+ parameter models to generate images on 8 GB consumer GPUs.", "limits": "Demonstrates lowering hardware barriers to local, unmonitored model execution.", "url": "https://huggingface.co/docs/diffusers/en/optimization/memory"}, "20": {"id": 20, "title": "Serverless GPU Infrastructure and Template Ecosystem Documentation", "publisher": "RunPod Inc.", "date": "2025-2026 documentation", "locator": "Serverless Endpoints & Community Cloud GPU Pricing", "status": "Primary source checked", "population": "On-demand cloud GPU compute users", "geo": "Global cloud infrastructure", "claim": "Provides on-demand serverless GPU execution starting at sub-dollar hourly rates, enabling commercial deepfake bot services to scale without owning hardware.", "limits": "Infrastructure provider documentation; highlights the supply chain role of cloud GPU hosts in abuse deployment.", "url": "https://docs.runpod.io/"}, "21": {"id": 21, "title": "Malicious Actors Manipulating Photos and Videos to Create Explicit Content and Sextortion Schemes", "publisher": "Federal Bureau of Investigation (IC3)", "date": "June 5, 2023", "locator": "Public Service Announcement Alert Number I-060523-PSA", "status": "Primary source checked", "population": "Victim reports submitted to FBI Internet Crime Complaint Center (IC3)", "geo": "United States (national advisory)", "claim": "FBI warned that benign photos posted on social media and public profiles are scraped and manipulated into synthetic sexually explicit content used for sextortion and harassment.", "limits": "Federal law enforcement advisory; observational threat intelligence based on voluntary public complaints.", "url": "https://www.ic3.gov/PSA/2023/PSA230605"}, "22": {"id": 22, "title": "FinCEN Issues Notice on Financially Motivated Sextortion Schemes", "publisher": "Financial Crimes Enforcement Network (US Dept of the Treasury)", "date": "July 2024", "locator": "FinCEN Notice FIN-2024-NTC2; Red Flags for Financial Institutions", "status": "Primary source checked", "population": "Suspicious Activity Reports (SARs) submitted by regulated financial entities", "geo": "United States and international remittance corridors", "claim": "Identified financially motivated sextortion involving AI-generated imagery as a critical financial crime, detailing payment mechanisms, gift card demands, and crypto conduits.", "limits": "Financial intelligence advisory; focuses on payment rails and illicit monetization rather than visual forensic analysis.", "url": "https://www.fincen.gov/news/news-releases/fincen-issues-notice-financially-motivated-sextortion"}, "23": {"id": 23, "title": "Recapping Our 2022 Coordinated Inauthentic Behavior Enforcements", "publisher": "Meta Threat Intelligence", "date": "December 2022", "locator": "Executive Summary & Adversarial Threat Report p. 6", "status": "Primary source checked", "population": "Coordinated inauthentic behavior (CIB) networks disrupted on Facebook and Instagram", "geo": "Global (networks originating in Russia, China, Iran, etc.)", "claim": "Over two-thirds (67%) of coordinated inauthentic behavior networks disrupted by Meta in 2022 utilized GAN-generated profile pictures to establish fake personas.", "limits": "Covers platform enforcements on political and influence operations; illustrates early widespread adoption of synthetic faces for fake identities.", "url": "https://about.fb.com/news/2022/12/metas-2022-coordinated-inauthentic-behavior-enforcements/"}, "24": {"id": 24, "title": "India-Based CIB Network: H2 2025 Threat Indicators", "publisher": "Meta Threat Research", "date": "Late 2025 release", "locator": "Threat Intelligence Dossier & IoC Hashes", "status": "Primary source checked", "population": "Cluster of coordinated accounts, pages, and groups operating in India", "geo": "India", "claim": "Documented network targeting domestic political discourse utilizing AI-generated female journalist and activist profiles with synthetic headshots and synthetic voices.", "limits": "Threat intelligence indicator release; attributes accounts to domestic PR entities, demonstrating non-consensual persona synthesis.", "url": "https://github.com/meta/threat-research/blob/main/indicators/meta-h2-2025-india-based-cib-network.md"}, "25": {"id": 25, "title": "Characteristics and Prevalence of Fake Social Media Profiles with AI-Generated Faces", "publisher": "Journal of Online Trust and Safety (Stanford University)", "date": "2023 peer-reviewed study", "locator": "Empirical Results: Corpus Analysis (Table 2, p. 14)", "status": "Primary source checked", "population": "Empirical dataset of 1,420 suspected accounts on X/Twitter exhibiting GAN-generated faces", "geo": "Global platform users", "claim": "Empirically analyzed 1,420 synthetic face profiles; identified key artifact characteristics (eye alignment, background blurring) and high rates of automated fraud and harassment.", "limits": "Focuses on StyleGAN2-era profile faces; newer diffusion models overcome several visual artifacts identified in this sample.", "url": "https://tsjournal.org/index.php/jots/article/view/197"}, "26": {"id": 26, "title": "OperationFFS: Fake Face Swarm Investigation", "publisher": "Graphika", "date": "September 2024", "locator": "Key Findings & Network Topology Section", "status": "Primary source checked", "population": "Multi-platform network spanning Facebook, X, LinkedIn, and YouTube", "geo": "Multi-regional", "claim": "Uncovered industrial-scale deployment of synthetic personas using latent diffusion portraits across corporate and social platforms to execute impersonation and reputational attacks.", "limits": "Investigative open-source intelligence report; demonstrates industrialization of persona generation beyond manual trolling.", "url": "https://www.graphika.com/reports/operationffs-fake-face-swarm"}, "27": {"id": 27, "title": "Our Approach to Labeling AI-Generated Content and Manipulated Media", "publisher": "Meta", "date": "April 2024", "locator": "Policy Update: AI Info Labels and Industry Signals", "status": "Primary source checked", "population": "All posts, reels, and stories across Facebook, Instagram, and Threads", "geo": "Global platform users", "claim": "Meta shifted from takedown-only policy to comprehensive 'AI info' labels applied via metadata detection (C2PA/IPTC) or self-disclosure.", "limits": "Labeling is dependent on intact metadata; malicious actors regularly strip metadata before uploading, rendering automated platform labels ineffective.", "url": "https://about.fb.com/news/2024/04/metas-approach-to-labeling-ai-generated-content-and-manipulated-media/"}, "28": {"id": 28, "title": "Understanding How Content Was Made Disclosures and C2PA Integration", "publisher": "YouTube (Google LLC)", "date": "2024 policy guidance", "locator": "Creator Requirements: Altered or Synthetic Content Policy", "status": "Primary source checked", "population": "All creators uploading video content to YouTube", "geo": "Global", "claim": "Requires creators to declare when realistic content is made with altered or synthetic media; displays labels and carries forward C2PA provenance credentials.", "limits": "Self-reporting reliance; non-consensual intimate imagery is strictly banned under harassment policies rather than labeled.", "url": "https://support.google.com/youtube/answer/15447836?hl=en"}, "29": {"id": 29, "title": "Community Guidelines: AI-Generated Content & Digital Forgery Rules", "publisher": "TikTok (ByteDance Ltd.)", "date": "2024-2025 guidelines", "locator": "Community Guidelines: Integrity and Authenticity Clause", "status": "Primary source checked", "population": "Global TikTok user base", "geo": "Global", "claim": "Mandates automated and creator-applied AI labels; strictly prohibits synthetic depictions of private figures without consent or sexualized synthetic likenesses of anyone.", "limits": "Platform terms govern distribution; does not prevent generation on offline consumer devices.", "url": "https://support.tiktok.com/en/using-tiktok/creating-videos/ai-generated-content"}, "30": {"id": 30, "title": "Synthetic and Manipulated Media Policy", "publisher": "X Corp.", "date": "2024 update", "locator": "Authenticity Rules: Deceptive Synthetic Media and NCII Prohibition", "status": "Primary source checked", "population": "Global users on X", "geo": "Global", "claim": "Prohibits sharing synthetic or manipulated media likely to cause harm, and imposes immediate zero-tolerance bans on non-consensual synthetic nudity.", "limits": "Relies heavily on victim reporting; automated detection of novel photorealistic faces without metadata remains poor.", "url": "https://help.x.com/en/rules-and-policies/authenticity"}, "31": {"id": 31, "title": "Guides Concerning the Use of Endorsements and Testimonials in Advertising", "publisher": "Federal Trade Commission", "date": "July 2023", "locator": "16 CFR Part 255; Section 255.5 (Virtual Influencers & Fake Personas)", "status": "Primary source checked", "population": "Commercial advertisers, agencies, and virtual influencer operators", "geo": "United States jurisdiction", "claim": "Clarified that deceptive commercial endorsements by synthetic personas, virtual influencers, and fabricated consumer reviews violate Section 5 of the FTC Act.", "limits": "Commercial consumer protection scope; does not directly cover non-commercial intimate harassment.", "url": "https://www.ftc.gov/news-events/news/press-releases/2023/06/federal-trade-commission-announces-updated-advertising-guides-combat-deceptive-reviews-endorsements"}, "32": {"id": 32, "title": "Reducing Risks Posed by Synthetic Content: An Overview, NIST AI 100-4", "publisher": "National Institute of Standards and Technology (NIST)", "date": "July 2024", "locator": "Executive Summary & Section 4 (Mitigation Techniques Taxonomy)", "status": "Primary source checked", "population": "Comprehensive technical literature and standards review", "geo": "United States / International Technical Standards", "claim": "Rigorous technical assessment concluding that watermarking, cryptographic metadata, and post-hoc detection are complementary but none constitutes a standalone preventative defense against determined adversaries.", "limits": "Authoritative institutional review; demonstrates inherent technical limits of relying solely on detection.", "url": "https://doi.org/10.6028/NIST.AI.100-4"}, "33": {"id": 33, "title": "C2PA Technical Specification: Content Credentials Version 2.5", "publisher": "Coalition for Content Provenance and Authenticity", "date": "2025 release", "locator": "Section 5: Manifest Structure, Assertion Stores, and Signature Verification", "status": "Primary source checked", "population": "Digital asset provenance standard implemented by Adobe, Microsoft, Google, etc.", "geo": "International industry standard", "claim": "Establishes cryptographic assertion framework binding author identity, capture device, and edit history to media containers.", "limits": "Easily stripped by taking a screenshot, converting file formats, or re-encoding media; cannot compel offline open-source models to sign manifests.", "url": "https://spec.c2pa.org/specifications/specifications/2.5/specs/C2PA_Specification.html"}, "34": {"id": 34, "title": "GenImage: A Million-Scale Benchmark for Detecting AI-Generated Image", "publisher": "Zhu, Chen, Yan, Guo, & Shen", "date": "NeurIPS 2023 (arXiv:2306.08571)", "locator": "Section 4: Cross-Generator Generalization Experiments (Table 3)", "status": "Primary source checked", "population": "1,331,167 images spanning 8 generative models (Stable Diffusion, Midjourney, DALL-E, etc.)", "geo": "Academic research benchmark", "claim": "Detectors trained on one generator suffer dramatic performance degradation (accuracy dropping from >99% to near random chance) when tested against unfamiliar modern generators.", "limits": "Proves the fundamental flaw of relying on post-hoc forensic classifiers to safeguard victims.", "url": "https://arxiv.org/abs/2306.08571"}, "35": {"id": 35, "title": "DailyBench: A Unified Benchmark for AI-Generated and Manipulated Images from Modern Generative Models", "publisher": "DailyBench Collaboration", "date": "July 2026 (arXiv:2607.24016)", "locator": "Section 3: Benchmark Construction & Cross-Architecture Evaluation", "status": "Primary source checked", "population": "Multi-modal evaluation across 2025-2026 generation architectures (Flux, SD3, Qwen-Image)", "geo": "International benchmark", "claim": "Evaluates localized facial inpainting and identity swapping; shows detection failure rates exceed 40% on fine-tuned LoRA adaptations.", "limits": "Empirical benchmark; confirms that forensic detection alone cannot keep pace with open-weight diffusion innovations.", "url": "https://arxiv.org/abs/2607.24016"}, "36": {"id": 36, "title": "Government Response on Regulatory Framework for Deepfakes and Synthetic Media", "publisher": "Press Information Bureau (Government of India)", "date": "February 2026", "locator": "Press Release PRID 2295500; Detailed Ministry Statement", "status": "Primary source checked", "population": "All social media intermediaries operating in India under the IT Act, 2000", "geo": "Republic of India", "claim": "Outlines statutory provisions against deepfakes under IT Act Sections 66C (identity theft), 66D (cheating by personation), 66E (privacy violation), 67, and 67A (sexually explicit content).", "limits": "Official government release explaining existing statutory framework and upcoming regulatory obligations.", "url": "https://www.pib.gov.in/PressReleasePage.aspx?PRID=2295500&lang=1&reg=1"}, "37": {"id": 37, "title": "Frequently Asked Questions on the IT (Intermediary Guidelines) Amendment Rules, 2026", "publisher": "Ministry of Electronics and Information Technology (MeitY)", "date": "February 2026", "locator": "Question 4: Synthetic Generated Information Due Diligence under Rule 3(3)", "status": "Primary source checked", "population": "Significant social media intermediaries and generative AI platforms", "geo": "India", "claim": "Provides administrative interpretation of Rule 3(3), defining mandatory due diligence obligations for platforms hosting or generating synthetic media.", "limits": "Regulatory administrative guidance; subject to ongoing judicial interpretation in Indian High Courts.", "url": "https://www.meity.gov.in/static/uploads/2026/02/49d4c4b42fc2d3dce00e0fdcf7ed1389.pdf"}, "38": {"id": 38, "title": "Artificial Intelligence Act, Regulation (EU) 2024/1689", "publisher": "European Parliament and Council of the European Union", "date": "Published July 12, 2024 (entered into force August 1, 2024)", "locator": "Article 50: Transparency Obligations for Providers and Deployers of AI Systems", "status": "Primary source checked", "population": "All AI providers and deployers offering services or placing systems on the EU single market", "geo": "European Union (27 Member States)", "claim": "Article 50(2) mandates deployers of deepfakes to disclose that content has been artificially generated or manipulated; Article 50(4) imposes machine-readable watermarking duties.", "limits": "Exceptions exist for artistic, creative, and satirical expression where appropriate; applies primarily to deployers rather than offline personal hobbyists.", "url": "https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-50?full=1"}, "39": {"id": 39, "title": "Guidelines on AI Transparency Obligations and Transition Timeline", "publisher": "European Commission (DG CNECT)", "date": "2025-2026 Guidance", "locator": "Section 2: Implementation Timetable for General Purpose AI & Article 50", "status": "Primary source checked", "population": "EU AI Office regulatory stakeholders", "geo": "European Union", "claim": "Confirms Article 50 transparency obligations apply formally from August 2, 2026, establishing penalties up to 35 million EUR or 7% of global annual turnover.", "limits": "Commission guidance on compliance timelines; fines represent statutory maximums.", "url": "https://digital-strategy.ec.europa.eu/en/policies/guidelines-ai-transparency-obligations"}, "40": {"id": 40, "title": "Complying with the Tools to Address Known Exploitation by Immobilizing Technological Deepfakes on Websites and Networks Act (TAKE IT DOWN Act)", "publisher": "Federal Trade Commission (Bureau of Consumer Protection)", "date": "May 2026", "locator": "Section 3: Mandatory Takedown Framework and 48-Hour Compliance Window", "status": "Primary source checked", "population": "All covered interactive computer services operating in the US", "geo": "United States", "claim": "Section 3 requires covered platforms to remove non-consensual intimate depictions and all known identical copies within 48 hours of receiving a qualifying notice from a victim.", "limits": "Applies to covered interactive services; does not govern peer-to-peer torrent distribution or local desktop inference.", "url": "https://www.ftc.gov/business-guidance/resources/complying-take-it-down-act"}, "41": {"id": 41, "title": "Crime and Policing Act 2026: Intimate Image Abuse Factsheet", "publisher": "Home Office (United Kingdom)", "date": "2026 Factsheet", "locator": "Factsheet Sections 2-4: Creation, Sharing, and Tool Supply Offenses", "status": "Primary source checked", "population": "Persons and commercial entities in England and Wales", "geo": "United Kingdom (England and Wales)", "claim": "Creates standalone criminal offenses for creating a sexually explicit deepfake without consent (regardless of whether shared), and for supplying tools purpose-built for such creation.", "limits": "Government factsheet explaining statutory provisions; criminal liability requires proof of intentional creation without reasonable belief in consent.", "url": "https://www.gov.uk/government/publications/crime-and-policing-act-2026-factsheets/crime-and-policing-act-2026-intimate-image-abuse-factsheet"}, "42": {"id": 42, "title": "Cybercrime and Digital Forgery Prosecution Guidance", "publisher": "Crown Prosecution Service (CPS)", "date": "2026 update", "locator": "Guidance on Non-Consensual Synthetic Intimate Imagery Offenses", "status": "Primary source checked", "population": "Crown prosecutors evaluating charging standards across England and Wales", "geo": "England and Wales", "claim": "Directs prosecutors to consider charges under both Communications Act / Online Safety Act provisions and Sexual Offences Act for non-consensual sexualized synthetic media.", "limits": "Prosecutorial charging guidance; evidentiary hurdles include proving defendant identity behind anonymous handles.", "url": "https://www.cps.gov.uk/prosecution-guidance/cybercrime-prosecution-guidance"}, "43": {"id": 43, "title": "Image-Based Abuse: Regulatory Overview and Powers", "publisher": "Australian eSafety Commissioner", "date": "2025-2026 overview", "locator": "Statutory Definitions & Civil Penalty Framework under Online Safety Act 2021", "status": "Primary source checked", "population": "Australian residents and services accessible within Australia", "geo": "Commonwealth of Australia", "claim": "Defines image-based abuse to include digitally altered, morphed, or synthesized realistic depictions; empowers eSafety to issue binding 24-hour removal notices to platforms.", "limits": "Statutory regulatory portal; non-compliance carries civil monetary penalties up to AUD 782,500 for corporations.", "url": "https://www.esafety.gov.au/key-topics/image-based-abuse"}, "44": {"id": 44, "title": "Bill C-16: Protecting Victims Act (Royal Assent)", "publisher": "Parliament of Canada", "date": "2025-2026 legislative session", "locator": "Clause 4: Amendments to Criminal Code Section 162.1", "status": "Primary source checked", "population": "Canadian federal criminal law jurisdiction", "geo": "Canada", "claim": "Explicitly amends Criminal Code section 162.1 (non-consensual distribution of intimate images) to include realistic synthetic and AI-generated depictions.", "limits": "Federal legislative statute; requires demonstration that the depiction would be understood by a reasonable person to depict an actual person.", "url": "https://www.parl.ca/documentviewer/en/45-1/bill/C-16/royal-assent?col=2"}, "45": {"id": 45, "title": "Government Reply to Inquiries Concerning Deepfakes and Dignitary Harms", "publisher": "House of Representatives (Japan)", "date": "2025 session", "locator": "Official Response b217084: Application of Penal Code Articles 230 & 231", "status": "Primary source checked", "population": "Legal jurisdiction of Japan", "geo": "Japan", "claim": "Cabinet confirms that synthesizing non-consensual sexualized imagery of an identifiable individual constitutes criminal defamation (Article 230) or insult (Article 231).", "limits": "Parliamentary cabinet response clarifying application of existing penal provisions; specific deepfake statute remains under study.", "url": "https://www.shugiin.go.jp/internet/itdb_shitsumon.nsf/html/shitsumon/b217084.htm"}, "46": {"id": 46, "title": "Act on Special Cases Concerning the Punishment, etc. of Sexual Crimes, Article 14-2", "publisher": "Korea Law Information Center", "date": "Amended 2024 / 2025", "locator": "Article 14-2: Manufacture, Distribution, etc. of False Video Recordings", "status": "Primary source checked", "population": "Republic of Korea jurisdiction", "geo": "South Korea", "claim": "Imposes criminal imprisonment up to 7 years or fines up to 50 million KRW for editing, synthesizing, or distributing false sexual recordings against the subject's will, including possessing or viewing with intent.", "limits": "Strict statutory text enacted following national school deepfake crisis; applies within Korean sovereign jurisdiction.", "url": "https://www.law.go.kr/lsInfoP.do?lsiSeq=265789&viewCls=engLsInfoR"}, "47": {"id": 47, "title": "PixArt-Sigma: Weak-to-Strong Training of Diffusion Transformers for 4K Image Synthesis", "publisher": "PixArt-alpha Team", "date": "2024 (arXiv:2403.04692)", "locator": "Architecture Specifications: 0.6B Parameter DiT Variant", "status": "Primary source checked", "population": "Diffusion Transformer (DiT) architecture for 4K generation", "geo": "Open-source research", "claim": "Achieves high-fidelity image synthesis with a 0.6B-parameter transformer backbone, demonstrating efficiency gains that lower execution barriers on edge devices.", "limits": "Academic research release; shows how distillation enables advanced generation on constrained hardware.", "url": "https://github.com/PixArt-alpha/PixArt-sigma"}, "48": {"id": 48, "title": "SANA: Efficient High-Resolution Image Synthesis with Linear Attention", "publisher": "NVlabs (NVIDIA Research)", "date": "October 2024 (arXiv:2410.10629)", "locator": "Linear Attention Formulation & 0.6B Parameter Model Benchmark", "status": "Primary source checked", "population": "Efficient linear diffusion model family", "geo": "Global open research", "claim": "Generates 1024x1024 imagery in under 1 second on consumer laptops by replacing quadratic attention with linear attention, scaling down to 0.6B parameters.", "limits": "Demonstrates rapid commoditization of high-speed local inference without cloud connectivity.", "url": "https://github.com/NVlabs/SANA"}, "49": {"id": 49, "title": "Z-Image-Turbo Technical Specifications", "publisher": "Tongyi-MAI (Alibaba Group)", "date": "2025 model card", "locator": "Model Details & Benchmark Latency", "status": "Primary source checked", "population": "6-billion-parameter accelerated image generator", "geo": "Open model ecosystem", "claim": "6B-parameter accelerated pipeline delivering sub-second photorealism across diverse linguistic prompts.", "limits": "Model card specification; subject to rapid community repackaging into uncensored local pipelines.", "url": "https://huggingface.co/Tongyi-MAI/Z-Image-Turbo"}, "50": {"id": 50, "title": "Lumina-Image 2.0: Unified Generative Framework", "publisher": "Alpha-VLLM Research Group", "date": "2025 release", "locator": "Architecture Overview & Diffusers Pipeline Integration", "status": "Primary source checked", "population": "Multi-resolution open visual generation framework", "geo": "Global open weights", "claim": "Unified architecture supporting text-to-image and image editing with flexible resolution support, widely adapted in community fine-tunes.", "limits": "Open-source research artifact with permissive research license.", "url": "https://huggingface.co/Alpha-VLLM/Lumina-Image-2.0/blob/main/README.md"}, "51": {"id": 51, "title": "The Information Technology Act, 2000 (Act No. 21 of 2000)", "publisher": "Ministry of Law and Justice (India Code)", "date": "Enacted 2000; amended 2008 & subsequent Rules", "locator": "Sections 66E (Privacy), 67 (Obscenity), 67A (Sexually Explicit Content)", "status": "Primary source checked", "population": "All electronic transactions and digital intermediaries in India", "geo": "India", "claim": "Primary statutory basis in India for prosecuting electronic privacy invasion (Section 66E: up to 3 years) and transmission of sexually explicit material (Section 67A: up to 5 years).", "limits": "Statutory foundation; older sections drafted before generative AI require ongoing regulatory rule-making for synthetic enforcement.", "url": "https://www.indiacode.nic.in/indiacode/handle/123456789/1999?locale=en"}, "52": {"id": 52, "title": "The Protection of Children from Sexual Offences (POCSO) Act, 2012", "publisher": "Ministry of Law and Justice (India Code)", "date": "Enacted 2012; amended 2019", "locator": "Sections 13, 14, and 15: Child Pornography Definitions and Penalties", "status": "Primary source checked", "population": "Children (defined as any person below age 18) within Indian jurisdiction", "geo": "India", "claim": "Sections 14 and 15 criminalize the storage, possession, and dissemination of child pornography; Supreme Court of India precedent confirms synthetic representations fall under strict liability.", "limits": "Strict liability criminal statute; does not require physical contact to substantiate serious penal offenses.", "url": "https://www.indiacode.nic.in/indiacode/handle/123456789/2079?view_type=browse"}, "53": {"id": 53, "title": "Deepfake Abuse is Abuse: Disrupting Harm Phase 2 Global Findings", "publisher": "UNICEF, ECPAT, and INTERPOL", "date": "February 2026", "locator": "Executive Summary & Research Methodology Footnote 3, p. 7", "status": "Primary source checked", "population": "Representative household survey of children aged 12–17 across 11 surveyed countries", "geo": "11 surveyed countries across Africa, Asia, and Latin America", "claim": "Estimated at least 1.2 million internet-using children aged 12–17 experienced sexual deepfake victimization in a single year across the 11 surveyed countries.", "limits": "Population-weighted survey estimate across 11 specific countries; must NOT be cited as an additive global total.", "url": "https://www.unicef.org/press-releases/deepfake-abuse-is-abuse"}, "54": {"id": 54, "title": "Through Children's Eyes: Technology-Facilitated Sexual Exploitation and Abuse", "publisher": "UNICEF Innocenti – Global Office of Research and Foresight", "date": "2025 report", "locator": "Key Findings: Table 1 (Prevalence) & Psychological Impact Section p. 28", "status": "Primary source checked", "population": "Representative survey across 21 countries; internet-using youth aged 12–17", "geo": "21 countries globally", "claim": "Estimated 20 million internet-using youth experienced technology-facilitated sexual exploitation or abuse; affected children had roughly fourfold higher odds of self-harm and suicidal ideation.", "limits": "Covers broader technology-facilitated abuse (online grooming, non-consensual sharing, and synthetic manipulation); correlations indicate severe distress but are not purely causal.", "url": "https://www.unicef.org/innocenti/reports/through-childrens-eyes"}, "55": {"id": 55, "title": "Hundreds of British Under-18s Reporting Nude or Sexual Imagery of Themselves Say It's Faked", "publisher": "Internet Watch Foundation & Childline", "date": "July 2026", "locator": "Operational Statistics Summary Table", "status": "Primary source checked", "population": "Reports from UK minors to IWF/Childline Report Remove service", "geo": "United Kingdom", "claim": "397 suspected-faked reports received (221 actioned) in full-year 2025, compared to 420 received (268 actioned) in just the first six months of 2026.", "limits": "Includes both AI generation and manual Photoshop morphing; based on self-reports by affected youth seeking takedown assistance.", "url": "https://www.iwf.org.uk/news-media/news/hundreds-of-british-under-18s-reporting-nude-or-sexual-imagery-of-themselves-say-its-faked-or-manipulated/"}, "56": {"id": 56, "title": "Deepfake Nudes and Young People: A National US Survey", "publisher": "Thorn", "date": "October 2024", "locator": "Executive Summary & Victimization Metrics, p. 5", "status": "Primary source checked", "population": "Nationally representative survey of 1,200 young people aged 13–20 in the United States", "geo": "United States", "claim": "Approximately 6% of teen respondents reported being the target of a deepfake nude creation, with female teens significantly more likely to experience reputational coercion.", "limits": "Self-report survey subject to recall bias; sampling weighted to US demographic census standards.", "url": "https://www.thorn.org/research/library/deepfake-nudes-and-young-people/"}, "57": {"id": 57, "title": "Beyond 'Revenge Porn': The Continuum of Image-Based Sexual Abuse", "publisher": "McGlynn, Rackley, & Houghton", "date": "Feminist Legal Studies 2021 (DOI: 10.1177/0964663920947791)", "locator": "Empirical Section: Qualitative Interviews (pp. 31-42)", "status": "Primary source checked", "population": "In-depth qualitative study of 75 victim-survivors across the UK, Australia, and New Zealand", "geo": "United Kingdom, Australia, New Zealand", "claim": "Documents profound, enduring harms: hypervigilance, social withdrawal, loss of employment, severe trauma, and complete rupture of trust in digital spaces.", "limits": "Qualitative semi-structured interview methodology; emphasizes lived experiences and psychological taxonomy rather than epidemiological prevalence.", "url": "https://doi.org/10.1177/0964663920947791"}, "58": {"id": 58, "title": "The Lived Experiences and Impacts of Sexualized Deepfake Abuse", "publisher": "PubMed / Journal of Sex Research", "date": "2024 (PMID: 42920292)", "locator": "Results: Victim-Survivor and Perpetrator Qualitative Profiles", "status": "Primary source checked", "population": "25 Australian adults (15 victim-survivors and 10 self-reported perpetrators)", "geo": "Australia", "claim": "Victim-survivors reported severe psychological trauma and institutional isolation; perpetrators expressed rationalizations grounded in perceived harmlessness and platform availability.", "limits": "Small qualitative cohort; provides crucial insights into perpetrator psychology and the false belief that synthetic media causes 'no real harm'.", "url": "https://pubmed.ncbi.nlm.nih.gov/42920292/"}, "59": {"id": 59, "title": "Hilliard Man Sentenced to 14 Years in Federal Prison for Using AI to Morph Minors' Images into CSAM", "publisher": "United States Department of Justice (USAO SDOH)", "date": "June 18, 2024", "locator": "Official Press Release & Sentencing Memorandum", "status": "Primary source checked", "population": "Federal criminal adjudication (United States v. Defendant)", "geo": "United States (Southern District of Ohio)", "claim": "Defendant sentenced to 14 years in federal prison after pleading guilty to producing and distributing child sexual abuse material generated by morphing faces of real local minors using AI.", "limits": "Adjudicated criminal conviction; proves that current federal statutes successfully apply to synthetic alterations of real children.", "url": "https://www.justice.gov/usao-sdoh/pr/hilliard-man-sentenced-14-years-prison-using-ai-morph-images-real-minors-child"}, "60": {"id": 60, "title": "Columbus Man Sentenced to 15 Years in Prison for Cyberstalking Exes and Creating AI-Generated Obscene Depictions", "publisher": "United States Department of Justice (USAO SDOH)", "date": "September 2024", "locator": "Official Press Release & Indictment Counts", "status": "Primary source checked", "population": "Federal criminal prosecution for multi-victim cyberstalking and digital forgery", "geo": "United States", "claim": "Defendant sentenced to 15 years in federal prison for cyberstalking multiple victims and disseminating AI-generated sexually explicit forgeries to their employers and families.", "limits": "Combined sentence covering multiple counts; aggregate duration reflects both interstate cyberstalking and digital forgery offenses.", "url": "https://www.justice.gov/usao-sdoh/pr/columbus-man-sentenced-15-years-prison-cyberstalking-exes-creating-ai-generated"}, "61": {"id": 61, "title": "Crime and Policing Act 2026: Explanatory Notes on Sections 72 and 99", "publisher": "UK Parliament / The National Archives", "date": "2026 statutory notes", "locator": "Division 11, Paragraphs 412-428: Generators of Purported Intimate Images", "status": "Primary source checked", "population": "Persons supplying, adapting, or facilitating image generation tools in the UK", "geo": "United Kingdom", "claim": "Sections 72 and 99 establish specific statutory liability for supplying software or models designed or adapted to generate CSAM or non-consensual intimate imagery, defining narrow technical exemptions.", "limits": "Official parliamentary explanatory notes interpreting statutory text; enforcement subject to Crown court jurisprudence.", "url": "https://www.legislation.gov.uk/ukpga/2026/20/notes/division/11/index.htm"}, "62": {"id": 62, "title": "FTC Begins Formal Enforcement of the TAKE IT DOWN Act", "publisher": "Federal Trade Commission", "date": "May 20, 2026", "locator": "Commission Policy Statement & Operational Guidelines", "status": "Primary source checked", "population": "Commercial websites, hosting services, and social platforms operating in the US", "geo": "United States", "claim": "FTC commenced formal nationwide enforcement of Section 3 of the Take It Down Act, establishing mandatory 48-hour takedown procedures with civil penalties up to $50,120 per violation.", "limits": "Regulatory enforcement launch announcement; establishes binding administrative duties for interactive computer services.", "url": "https://www.ftc.gov/news-events/news/press-releases/2026/05/ftc-begins-enforcing-take-it-down-act"}, "63": {"id": 63, "title": "Dual-Use Foundation Models with Widely Available Model Weights", "publisher": "National Telecommunications and Information Administration (NTIA)", "date": "July 2024", "locator": "Executive Summary & Policy Recommendations 1-3, pp. 6-12", "status": "Primary source checked", "population": "Comprehensive federal multi-stakeholder inquiry on open-weight AI models", "geo": "United States (federal executive branch)", "claim": "NTIA concluded that current evidence does not warrant immediate blanket restrictions on open model weights, recommending active monitoring while preserving the option for targeted restrictions if critical marginal risks emerge.", "limits": "US government policy report; balances open-source innovation against national security and civil protection risks.", "url": "https://www.ntia.gov/sites/default/files/publications/ntia-ai-open-model-report.pdf"}, "64": {"id": 64, "title": "National Cyber Crime Reporting Portal (cybercrime.gov.in) Citizen Interface", "publisher": "Ministry of Home Affairs (Government of India)", "date": "Accessed 2026", "locator": "Citizen Guidance: Reporting Cyber Crimes Against Women and Children", "status": "Primary source checked", "population": "Citizens filing cybercrime reports across India", "geo": "Republic of India", "claim": "Centralized statutory reporting portal with dedicated priority intake for sexually explicit content, CSAM, and digital impersonation, integrated with local state police jurisdictions and the 1930 Helpline.", "limits": "Statutory operational portal; reporting volume and speed of local police registration vary across state cyber cells.", "url": "https://www.cybercrime.gov.in/webform/FAQ.aspx"}, "65": {"id": 65, "title": "Non-Consensual Synthetic Intimate Imagery: Prevalence, Attitudes, and Knowledge in 10 Countries", "publisher": "Umbach, Henry, Beard, & Berryessa", "date": "ACM CHI 2024 (DOI: 10.1145/3613904.3642382)", "locator": "Section 4.1: Prevalence of Victimization and Perpetration Across 10 Countries", "status": "Primary source checked", "population": "16,145 adult survey respondents across 10 diverse countries (US, UK, India, Brazil, Japan, etc.)", "geo": "10-country international sample", "claim": "2.2% of respondents self-reported personal victimization by non-consensual synthetic intimate imagery, while 1.8% admitted to generating or commissioning such content.", "limits": "Self-report survey design; vulnerable to underreporting due to stigma, but represents the largest cross-national academic survey to date.", "url": "https://doi.org/10.1145/3613904.3642382"}, "66": {"id": 66, "title": "The Ecosystem of Nonconsensual Intimate Deepfake Tools Online", "publisher": "Institute for Strategic Dialogue (ISD)", "date": "June 2025", "locator": "Executive Summary & Traffic Analysis Table 1, p. 3", "status": "Primary source checked", "population": "31 identified dedicated websites offering commercial non-consensual intimate image generation", "geo": "Global web traffic (SimilarWeb telemetry)", "claim": "The 31 sampled deepfake websites collectively attracted an estimated 20.7 million visits in the month of May 2025 alone.", "limits": "Visits do not equal unique users, perpetrators, or generated images; reflects aggregate web engagement with commercial undressing services.", "url": "https://www.isdglobal.org/digital-dispatch/the-ecosystem-of-nonconsensual-intimate-deepfake-tools-online/"}, "67": {"id": 67, "title": "'There Are No Limits!': AI Undressing Apps and the Normalization of Nonconsensual Intimate Deepfakes", "publisher": "Violence Against Women (Sage Publishing)", "date": "2025 (DOI: 10.1177/10778012251397966)", "locator": "Methodology & Table 1: Audit of 29 Commercial Undressing Applications", "status": "Primary source checked", "population": "29 commercially available web, mobile, and Telegram-based undressing applications", "geo": "Global commercial services", "claim": "Systematic audit revealed aggressive predatory marketing, gamified coin architectures, complete absence of age or consent verification, and deceptive privacy disclaimers.", "limits": "App audit sample of 29 prominent services; demonstrates predatory business models normalizing non-consensual generation.", "url": "https://doi.org/10.1177/10778012251397966"}, "68": {"id": 68, "title": "How Common is the Experience of Image-Based Abuse Among Children in Australia?", "publisher": "Australian eSafety Commissioner", "date": "2025 Research Brief", "locator": "Section: Experiences of Fabricated and Manipulated Imagery, p. 8", "status": "Primary source checked", "population": "1,948 Australian children aged 10–17 responding to the specialized image abuse module", "geo": "Australia", "claim": "3% of Australian children reported having had a fabricated nude image of themselves made without permission in their lifetime; 1% experienced it in the past 12 months.", "limits": "Representative national survey of Australian youth; reflects direct child disclosures under rigorous ethical safeguarding protocols.", "url": "https://www.esafety.gov.au/research/the-online-experiences-of-children-in-australia/experiences-of-image-based-abuse"}, "69": {"id": 69, "title": "eSafety Action Prevents Services Nudifying Australian School Children", "publisher": "Australian eSafety Commissioner", "date": "July 2024", "locator": "Media Release & Regulatory Enforcement Summary", "status": "Primary source checked", "population": "Enforcement notices issued to offshore undressing websites and formal engagement with Hugging Face", "geo": "Australia / Global platform engagement", "claim": "Following regulatory intervention, 3 targeted deepfake services withdrew access in Australia, and Hugging Face revised its terms and moderation following formal eSafety engagement.", "limits": "Official regulatory outcome release; illustrates that proactive regulatory scrutiny can compel model-hosting intermediaries to act.", "url": "https://www.esafety.gov.au/newsroom/media-releases/esafety-action-prevents-services-nudifying-australian-school-children"}, "70": {"id": 70, "title": "Submission on the Online Safety Amendment (Digital Duty of Care) Bill 2026", "publisher": "Australian eSafety Commissioner", "date": "November 2026", "locator": "Section 3.2: supply-chain interventions & Table of Disrupted Services, p. 19", "status": "Primary source checked", "population": "Regulatory oversight of high-traffic generative abuse portals", "geo": "Commonwealth of Australia", "claim": "8 prominent services collectively generating >200,000 monthly Australian visits withdrew access or deployed geoblocking compliance following formal eSafety action.", "limits": "Submission to Australian Senate Committee; notes that geoblocking can be circumvented by VPNs and calls for upstream foundation model governance.", "url": "https://www.esafety.gov.au/sites/default/files/2026-11/eSafety_submission_Digital_Duty_of_Care_Bill_Senate_Committee_Inquiry.pdf"}, "71": {"id": 71, "title": "Federal Court Orders AUD 343,500 Penalty for Posting Deepfakes of Australian Women", "publisher": "Federal Court of Australia (via eSafety Commissioner)", "date": "October 2024", "locator": "Court Judgment Summary & Civil Penalty Order", "status": "Primary source checked", "population": "Civil enforcement action against individual perpetrator (eSafety Commissioner v. Individual)", "geo": "Australia", "claim": "Federal Court ordered AUD 343,500 in civil penalties plus costs against an individual for repeatedly publishing sexually explicit deepfakes of Australian women on foreign forums.", "limits": "Landmark civil penalty order; represents judicial enforcement rather than private victim damages or criminal sentencing.", "url": "https://www.esafety.gov.au/newsroom/media-releases/court-orders-343500-penalty-for-posting-deepfakes-of-australian-women"}, "72": {"id": 72, "title": "FTC Sends Warning Letters to Companies About Compliance with the TAKE IT DOWN Act", "publisher": "Federal Trade Commission", "date": "May 2026", "locator": "Press Release & Sample Warning Letter Text", "status": "Primary source checked", "population": "12 technology platforms and interactive services", "geo": "United States", "claim": "FTC issued formal warning letters to 12 commercial interactive platforms for apparent failure to implement accessible 48-hour takedown submission mechanisms.", "limits": "Warning letters indicate pre-enforcement scrutiny; does not constitute a final adjudicated finding of statutory non-compliance.", "url": "https://www.ftc.gov/news-events/news/press-releases/2026/05/ftc-sends-warning-letters-companies-about-compliance-take-it-down-act"}, "73": {"id": 73, "title": "Enforcement Programme into Measures to Prevent Users from Encountering or Sharing Non-Consensual Intimate Imagery (NCII)", "publisher": "Ofcom (Office of Communications, UK)", "date": "2025-2026 programme update", "locator": "Programme Findings: Tiers of Service Compliance & Investigation Notices", "status": "Primary source checked", "population": "25 high-risk and high-reach online services operating in the UK", "geo": "United Kingdom", "claim": "Engaged 25 high-risk platforms; multiple services implemented automated hash matching or UK access restrictions, with formal statutory investigations opened against non-cooperative entities.", "limits": "Ongoing regulatory supervisory programme under the UK Online Safety Act 2023.", "url": "https://www.ofcom.org.uk/online-safety/illegal-and-harmful-content/Enforcement-programme-into-measures-being-taken-by-services-to-prevent-users-from-encountering-or-sharing-non-consensual-intimate-imagery-NCII"}, "74": {"id": 74, "title": "Consolidated Information Technology (Intermediary Guidelines and Digital Media Ethics Code) Rules, 2021 (as amended through 2026)", "publisher": "Ministry of Electronics and Information Technology (MeitY)", "date": "Gazette notification 2021, amended 2026", "locator": "Rule 3(1)(d) (3-Hour Window) and Rule 3(2)(b) (2-Hour Expedited Action Trigger)", "status": "Primary source checked", "population": "All digital intermediaries operating in India", "geo": "Republic of India", "claim": "Rule 3(2)(b) establishes expedited 2-hour window for intermediaries to disable access to non-consensual intimate imagery upon complaint; Rule 3(1)(d) sets 3-hour limit upon actual knowledge.", "limits": "Strict regulatory deadlines; operational compliance challenges exist for offshore platforms lacking domestic grievance officers.", "url": "https://www.meity.gov.in/static/uploads/2026/03/0b576f2071694b52e4cd6bb1b6dfab1e.pdf"}, "75": {"id": 75, "title": "Online Safety Risk Assessments Report: Year One Review", "publisher": "Ofcom", "date": "2026 report", "locator": "Page 18 (PDF p. 19), Table 4: Governance and Ownership Findings", "status": "Primary source checked", "population": "104 reviewed risk assessment records submitted by online services to Ofcom", "geo": "United Kingdom", "claim": "69 of 104 reviewed risk assessment records (66.35%) failed to name a designated responsible officer accountable for safety mitigations.", "limits": "CORRECTION NOTE: Located on printed page 18 (PDF page 19), not page 17 as cited in preliminary drafts; sample consists of reviewed records rather than total market firms.", "url": "https://www.ofcom.org.uk/siteassets/resources/documents/online-safety/research-statistics-and-data/os-standards/online-safety-risk-assessments-report-year-one.pdf?v=408834"}, "76": {"id": 76, "title": "Operation Cumberland on AI-Generated Child Sexual Abuse Material", "publisher": "Council of Europe / Europol", "date": "2025 operational dispatch", "locator": "Operational Summary & Joint Investigation Findings", "status": "Primary source checked", "population": "Multinational law enforcement operation spanning multiple European police services", "geo": "Pan-European (Denmark, Bosnia & Herzegovina, etc.)", "claim": "Coordinated international law enforcement operation resulting in 25 arrests of individuals generating and distributing AI-generated CSAM via encrypted chat channels.", "limits": "Law enforcement arrest tally; arrests reflect initial criminal apprehensions and charges rather than final trial verdicts.", "url": "https://www.coe.int/en/web/cybercrime/-/denmark-bosnia-and-herzegovina-and-others-operation-cumberland-on-ai-generated-child-sexual-abuse-material"}};
  function openCitationModal(id) {
    const data = CITATION_DATA[id];
    if (!data) return false;
    const modal = document.getElementById('citation-inspector-modal');
    if (!modal) return false;
    document.getElementById('citation-modal-ref').textContent = 'Audited Evidence Citation [' + data.id + ']';
    document.getElementById('citation-modal-title').textContent = data.title;
    document.getElementById('citation-modal-pub').textContent = data.publisher;
    document.getElementById('citation-modal-date').textContent = data.date;
    document.getElementById('citation-modal-locator').textContent = data.locator || 'Detailed citation in primary document';
    document.getElementById('citation-modal-status').textContent = data.status || 'Primary source checked';
    document.getElementById('citation-modal-pop').textContent = data.population || 'Documented cohort / statutory jurisdiction';
    document.getElementById('citation-modal-geo').textContent = data.geo || 'Global / Multi-jurisdiction';
    document.getElementById('citation-modal-claim').textContent = data.claim;
    document.getElementById('citation-modal-limits').textContent = data.limits || 'Refer to primary source methodology and scope.';
    const link = document.getElementById('citation-modal-link');
    if (link) {
      link.href = data.url || '#';
      link.style.display = data.url ? 'inline-flex' : 'none';
    }
    const full = document.getElementById('citation-modal-full');
    if (full) {
      full.href = '/sources/#source-' + data.id;
    }
    modal.hidden = false;
    document.body.style.overflow = 'hidden';
    return true;
  }
  function closeCitationModal() {
    const modal = document.getElementById('citation-inspector-modal');
    if (modal) {
      modal.hidden = true;
      document.body.style.overflow = '';
    }
  }
  document.addEventListener('keydown', e => {
    if (e.key === 'Escape') closeCitationModal();
  });

  function update(root){
    const q = (root.querySelector('[data-search]')?.value || '').trim().toLowerCase();
    const filters = [...root.querySelectorAll('[data-select]')];
    let count=0; root.querySelectorAll('[data-record]').forEach(el=>{
      const match=el.textContent.toLowerCase().includes(q)&&filters.every(f=>!f.value||el.dataset[f.dataset.select]===f.value);
      el.hidden=!match; if(match)count++;
    });
    const counter=root.querySelector('[data-count]'); if(counter)counter.textContent=`${count} matching records`;
    const empty=root.querySelector('[data-empty]');if(empty)empty.hidden=count!==0;
  }
  document.addEventListener('input', e=>{if(e.target.matches('[data-search]')) update(e.target.closest('[data-filter-root]'));});
  document.addEventListener('change', e=>{if(e.target.matches('[data-select]')) update(e.target.closest('[data-filter-root]'));});
  document.addEventListener('click', async e=>{
    const menu=e.target.closest('[data-menu]');if(menu){const expanded=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',String(!expanded));document.getElementById('main-nav').classList.toggle('open',!expanded);return;}
    const dropdownBtn=e.target.closest('[data-dropdown-btn]');
    if(dropdownBtn){
      const item=dropdownBtn.closest('[data-dropdown]');
      const isOpen=item.classList.contains('open');
      document.querySelectorAll('[data-dropdown].open').forEach(d=>{if(d!==item){d.classList.remove('open');d.querySelector('[data-dropdown-btn]')?.setAttribute('aria-expanded','false');}});
      item.classList.toggle('open',!isOpen);
      dropdownBtn.setAttribute('aria-expanded',String(!isOpen));
      return;
    }
    if(!e.target.closest('[data-dropdown]')){
      document.querySelectorAll('[data-dropdown].open').forEach(d=>{d.classList.remove('open');d.querySelector('[data-dropdown-btn]')?.setAttribute('aria-expanded','false');});
    }
    const tab=e.target.closest('[data-chart-tab]');if(tab){const group=tab.closest('[data-chart-group]');group.querySelectorAll('[data-chart-tab]').forEach(t=>t.setAttribute('aria-pressed',String(t===tab)));group.querySelectorAll('[data-chart-panel]').forEach(p=>p.hidden=p.dataset.chartPanel!==tab.dataset.chartTab);return;}
    const cite=e.target.closest('[data-citation]');
    if(cite){
      const id = cite.dataset.citation;
      if(openCitationModal(id)){ e.preventDefault(); return; }
    }
    if(e.target.closest('[data-citation-close]')){
      closeCitationModal();
      return;
    }
    const copy=e.target.closest('[data-copy]');if(copy){const input=document.getElementById(copy.dataset.copy);const status=copy.parentElement.querySelector('[data-copy-status]');try{await navigator.clipboard.writeText(input.value);status.textContent='Letter copied.';}catch{input.select();status.textContent='Select Copy or press Ctrl+C / Cmd+C to copy.';}return;}
    if(e.target.closest('#main-nav a')){
      document.getElementById('main-nav')?.classList.remove('open');
      document.querySelector('[data-menu]')?.setAttribute('aria-expanded','false');
      document.querySelectorAll('[data-dropdown].open').forEach(d=>{d.classList.remove('open');d.querySelector('[data-dropdown-btn]')?.setAttribute('aria-expanded','false');});
    }
  });
  document.addEventListener('submit', e=>{
    const form=e.target.closest('[data-signup-form]');
    if(form){
      e.preventDefault();
      const status=form.querySelector('[data-signup-status]');
      if(status){
        status.textContent='Public registration intake is currently paused pending dedicated server deployment.';
        status.style.color='#6e626b';
      }
    }
  });
  const active=()=>{const p=location.pathname.replace(/index\.html$/,'').replace(/\/$/,'')||'/';document.querySelectorAll('[data-nav]').forEach(a=>{const path=new URL(a.href,location.href).pathname.replace(/index\.html$/,'').replace(/\/$/,'')||'/';if(p===path)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});};
  active();window.addEventListener('popstate',active);
  // Static routes may be client-navigated by Next. Synchronize active state on route changes.
  let last=location.pathname; new MutationObserver(()=>{if(last!==location.pathname){last=location.pathname;active();}}).observe(document.body,{childList:true,subtree:true});
})();
